using System; using System.IO; using System.Linq;  namespace Monthly_Excel.Utils {     public static class WebView2TempManager     {         private const string RootFolderName = "MonthlyExcel_WebView2";          public static string RootPath =>             Path.Combine(Path.GetTempPath(), RootFolderName);          public static string CreateSessionFolder()         {             Directory.CreateDirectory(RootPath);              string sessionFolder = Path.Combine(                 RootPath,                 DateTime.Now.ToString("yyyyMMdd_HHmmss_fff") + "_" + Guid.NewGuid().ToString("N")             );              Directory.CreateDirectory(sessionFolder);             return sessionFolder;         }          public static void CleanupOldSessionFolders(TimeSpan olderThan)         {             try             {                 if (!Directory.Exists(RootPath))                     return;                  var root = new DirectoryInfo(RootPath);                 var threshold = DateTime.Now - olderThan;                  foreach (var dir in root.GetDirectories())                 {                     try                     {                         var lastWrite = dir.LastWriteTime;                         if (lastWrite < threshold)                         {                             TryDeleteDirectory(dir.FullName);                         }                     }                     catch                     {                     }                 }             }             catch             {             }         }          public static void CleanupAllExcept(string? keepPath)         {             try             {                 if (!Directory.Exists(RootPath))                     return;                  var root = new DirectoryInfo(RootPath);                  foreach (var dir in root.GetDirectories())                 {                     try                     {                         if (!string.IsNullOrWhiteSpace(keepPath) &&                             string.Equals(                                 Path.GetFullPath(dir.FullName).TrimEnd(Path.DirectorySeparatorChar),                                 Path.GetFullPath(keepPath).TrimEnd(Path.DirectorySeparatorChar),                                 StringComparison.OrdinalIgnoreCase))                         {                             continue;                         }                          TryDeleteDirectory(dir.FullName);                     }                     catch                     {                     }                 }             }             catch             {             }         }          public static bool TryDeleteDirectory(string path)         {             try             {                 if (!Directory.Exists(path))                     return true;                  RemoveReadOnlyRecursive(path);                 Directory.Delete(path, true);                 return true;             }             catch             {                 return false;             }         }          private static void RemoveReadOnlyRecursive(string path)         {             try             {                 foreach (string file in Directory.EnumerateFiles(path, "*", SearchOption.AllDirectories))                 {                     try                     {                         File.SetAttributes(file, FileAttributes.Normal);                     }                     catch                     {                     }                 }                  foreach (string dir in Directory.EnumerateDirectories(path, "*", SearchOption.AllDirectories).Reverse())                 {                     try                     {                         File.SetAttributes(dir, FileAttributes.Directory);                     }                     catch                     {                     }                 }                  File.SetAttributes(path, FileAttributes.Directory);             }             catch             {             }         }     } }